from pathlib import Path

wiki_path = Path("/home/zhouhuijuan1987/wiki/youtube-video-research-wiki/wiki")
print("Wiki directory contents:")
for item in wiki_path.rglob("*"):
    if item.is_file():
        print(f"  {item.relative_to(wiki_path)}")
    elif item.is_dir():
        print(f"  {item.relative_to(wiki_path)}/")

print("\nChecking specific directories:")
for subdir in ["sources", "entities", "concepts", "comparisons", "overview", "queries"]:
    subdir_path = wiki_path / subdir
    if subdir_path.exists():
        files = list(subdir_path.glob("*.md"))
        print(f"  {subdir}/: {len(files)} files")
        for f in files[:3]:  # Show first 3 files
            print(f"    - {f.name}")
        if len(files) > 3:
            print(f"    ... and {len(files) - 3} more")
    else:
        print(f"  {subdir}/: directory does not exist")"}
